// NEET UG Biology: Animal kingdom (NCERT Class 11, Chapter 4). All questions original fibub work.
import { pick, int, choose, fmt, shuffleOpts, numOpts, g } from '../_entrance.js';

const E = ['neet'];
const items = [];
const groups = {};
let n = 0, pos = 0;
const POS = [2, 0, 3, 1];
const nid = () => `ak-${String(++n).padStart(3, '0')}`;
const AR = ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'];
const ST = ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'];
function mc(level, sub, q, correct, wrongs, sol, trap, format = 'single') {
  const p = POS[pos++ % 4];
  const options = [...wrongs];
  options.splice(p, 0, correct);
  items.push({ id: nid(), type: 'mcq', level, format, exams: E, sub, q, options, answer: p, sol, ...(trap ? { trap } : {}) });
}
function asr(level, sub, A, R, ans, sol, trap) {
  items.push({ id: nid(), type: 'mcq', level, format: 'assertion', exams: E, sub, q: `<b>Assertion (A):</b> ${A}<br><b>Reason (R):</b> ${R}`, options: AR, answer: ans, sol, ...(trap ? { trap } : {}) });
}
function stm(level, sub, s1, s2, ans, sol, trap) {
  items.push({ id: nid(), type: 'mcq', level, format: 'statements', exams: E, sub, q: `<b>Statement I:</b> ${s1}<br><b>Statement II:</b> ${s2}`, options: ST, answer: ans, sol, ...(trap ? { trap } : {}) });
}
function match(level, sub, key, title, list1, list2, correct, wrongs, sol, trap) {
  groups[key] = { title, list1, list2 };
  const p = POS[pos++ % 4];
  const options = [...wrongs]; options.splice(p, 0, correct);
  items.push({ id: nid(), type: 'mcq', level, format: 'match', exams: E, sub, group: key, q: 'Match List I with List II and choose the correct code.', options, answer: p, sol, ...(trap ? { trap } : {}) });
}
function pass(key, title, passage) { groups[key] = { title, passage }; }
function pq(key, level, sub, q, correct, wrongs, sol, trap) {
  const p = POS[pos++ % 4];
  const options = [...wrongs]; options.splice(p, 0, correct);
  items.push({ id: nid(), type: 'mcq', level, format: 'passage', exams: E, sub, group: key, q, options, answer: p, sol, ...(trap ? { trap } : {}) });
}
// ---------------------------------------------------------------- Level 1
mc(1, 'levels of organisation', 'Sponges show which level of body organisation?', 'Cellular level', ['Tissue level', 'Organ level', 'Organ-system level'], 'In Porifera the cells are arranged as loose aggregates with some division of labour, but they are not organised into true tissues. This is the cellular level.');
mc(1, 'symmetry', 'If any plane passing through the central axis divides the body into two equal halves, the animal shows', 'radial symmetry', ['bilateral symmetry', 'asymmetry', 'metameric symmetry'], 'In radial symmetry any plane through the central axis gives two similar halves, as in Hydra and sea anemone. In bilateral symmetry only one plane does so.');
mc(1, 'germ layers', 'Animals whose embryo has ectoderm, mesoderm and endoderm are called', 'triploblastic', ['diploblastic', 'acoelomate', 'monoblastic'], 'Triploblastic animals have three germ layers. Diploblastic animals have only ectoderm and endoderm, with a jelly-like mesoglea between them.');
mc(1, 'notochord', 'The notochord is a', 'mesoderm-derived rod-like structure on the dorsal side', ['ectoderm-derived hollow tube on the ventral side', 'endoderm-derived gill support', 'bony column that replaces the skull'], 'The notochord is a long rod formed from mesoderm during embryonic development, running along the back. Chordates have it at some stage; non-chordates never do.');
mc(1, 'phylum Porifera', 'Which phylum is made of animals with pores on the body, a canal system, and a skeleton of spicules or spongin?', 'Porifera', ['Cnidaria', 'Ctenophora', 'Echinodermata'], 'Porifera means pore bearer. Water enters through many ostia, passes the spongocoel and leaves through the osculum.');
mc(1, 'phylum Cnidaria', 'Stinging cells called cnidoblasts are found in', 'Cnidaria', ['Porifera', 'Platyhelminthes', 'Mollusca'], 'Cnidoblasts (cnidocytes) with nematocysts are the mark of Cnidaria, used for anchorage, defence and capture of prey.');
mc(1, 'phylum Platyhelminthes', '<i>Taenia</i> and <i>Fasciola</i> are', 'flatworms', ['roundworms', 'segmented worms', 'comb jellies'], 'Both are parasitic members of Platyhelminthes. The tapeworm is <i>Taenia</i> and the liver fluke is <i>Fasciola</i>.');
mc(1, 'phylum Annelida', 'The earthworm <i>Pheretima</i> belongs to the phylum', 'Annelida', ['Aschelminthes', 'Arthropoda', 'Platyhelminthes'], 'Earthworms have a body divided into ring-like segments, the mark of Annelida.');
mc(1, 'phylum Arthropoda', 'Which is the largest phylum of the animal kingdom?', 'Arthropoda', ['Mollusca', 'Chordata', 'Annelida'], 'Over two-thirds of all named species are arthropods, mostly insects. Mollusca is the second largest.');
mc(1, 'phylum Mollusca', 'The file-like rasping organ used for feeding in molluscs is the', 'radula', ['mantle', 'proboscis', 'pinna'], 'The radula is found in the mouth of most molluscs. The mantle is the skin fold over the visceral hump.');
mc(1, 'phylum Echinodermata', 'The water vascular system is a distinctive feature of', 'Echinodermata', ['Hemichordata', 'Cnidaria', 'Annelida'], 'Starfish, sea urchins and their relatives use the water vascular system for locomotion, food capture and respiration.');
mc(1, 'Chordata', 'Amphioxus is placed in the subphylum', 'Cephalochordata', ['Urochordata', 'Vertebrata', 'Hemichordata'], '<i>Branchiostoma</i> (Amphioxus or lancelet) has a notochord that runs from head to tail and stays for life.');
mc(1, 'Mammalia', 'Mammary glands and hair are the hallmarks of class', 'Mammalia', ['Aves', 'Reptilia', 'Amphibia'], 'All mammals have mammary glands that feed the young. Hair is unique to the mammalian skin.');
mc(1, 'Aves', 'The heart of a bird is', 'four-chambered', ['two-chambered', 'three-chambered', 'single-chambered'], 'Birds have two auricles and two ventricles, and are warm-blooded.');
mc(1, 'Chondrichthyes', 'The cartilaginous fish such as <i>Scoliodon</i> belong to class', 'Chondrichthyes', ['Osteichthyes', 'Cyclostomata', 'Amphibia'], 'Chondrichthyes have a cartilaginous endoskeleton. <i>Scoliodon</i> is the dogfish shark.');

// ---------------------------------------------------------------- Level 2
mc(2, 'segmentation', 'The external and internal division of the body into repeated segments is called', 'metamerism', ['metagenesis', 'metamorphosis', 'cephalisation'], 'Metamerism is seen in Annelida, where the body has serially repeated units, and in a way in Arthropoda and Chordata. Metagenesis means alternation of polyp and medusa.');
mc(2, 'coelom', 'A true coelom is', 'a body cavity lined by mesoderm', ['a body cavity not lined by mesoderm', 'a cavity lined by endoderm only', 'absence of any body cavity'], 'In coelomates the body cavity is fully lined by mesoderm. In pseudocoelomates the mesoderm is present only as scattered pouches between ectoderm and endoderm.');
mc(2, 'coelom', 'Which animals are pseudocoelomates?', 'Aschelminthes', ['Annelida', 'Platyhelminthes', 'Arthropoda'], 'Roundworms have a body cavity not lined by mesoderm. Flatworms are acoelomate; annelids and arthropods are coelomate.');
mc(2, 'coelom', 'Platyhelminthes are', 'acoelomate', ['pseudocoelomate', 'coelomate', 'diploblastic'], 'Flatworms have no body cavity between the body wall and gut, though they are triploblastic.');
mc(2, 'phylum Porifera', 'In a sponge, the cells that line the spongocoel and canals and drive the water current are', 'choanocytes (collar cells)', ['cnidoblasts', 'nematocytes', 'flame cells'], 'Flagellated choanocytes create the water current that brings food and oxygen, and digestion inside them is intracellular.');
mc(2, 'phylum Porifera', 'Which statement about sponges is correct?', 'Sexes are not separate and development is indirect with a larva', ['Sexes are separate and development is direct', 'Fertilisation is external and there is no larva', 'They reproduce only sexually'], 'Sponges are hermaphrodite (monoecious); the egg and sperm are made by the same individual. Fertilisation is internal and the larva looks different from the adult. They also reproduce asexually by fragmentation.');
mc(2, 'phylum Porifera', 'The bath sponge is', '<i>Euspongia</i>', ['<i>Spongilla</i>', '<i>Sycon</i>', '<i>Physalia</i>'], '<i>Euspongia</i> is the bath sponge. <i>Spongilla</i> is the freshwater sponge, <i>Sycon</i> a marine one, and <i>Physalia</i> a cnidarian.');
mc(2, 'phylum Cnidaria', 'The two basic body forms of Cnidaria are', 'polyp and medusa', ['trochophore and veliger', 'bipinnaria and pluteus', 'protonema and prothallus'], 'The polyp is sessile and cylindrical (<i>Hydra</i>). The medusa is umbrella-shaped and free-swimming (<i>Aurelia</i>).');
mc(2, 'phylum Cnidaria', '<i>Obelia</i> shows alternation of generation, called', 'metagenesis between polyp and medusa', ['metamerism', 'bioluminescence', 'regeneration'], 'Cnidarians that exist in both polyp and medusa forms show metagenesis. <i>Obelia</i> is a standard example.');
mc(2, 'phylum Cnidaria', 'The mouth opening of a cnidarian is on the raised part called', 'hypostome', ['proboscis', 'osculum', 'operculum'], 'The gastro-vascular cavity opens by a single opening, the mouth on the hypostome. It also serves as the anus.');
mc(2, 'phylum Ctenophora', 'Comb jellies have', 'eight external rows of ciliated comb plates', ['eight pairs of walking legs', 'a ring of nematocyst-bearing tentacles only', 'eight chambers in the stomach'], 'The comb plates help in locomotion. Ctenophores are marine, radially symmetrical and diploblastic.');
mc(2, 'phylum Ctenophora', 'Which of the following is a ctenophore?', '<i>Pleurobrachia</i>', ['<i>Adamsia</i>', '<i>Aurelia</i>', '<i>Antedon</i>'], '<i>Pleurobrachia</i> (sea walnut) and <i>Ctenoplana</i> are ctenophores. <i>Adamsia</i> and <i>Aurelia</i> are cnidarians; <i>Antedon</i> is an echinoderm.');
mc(2, 'phylum Platyhelminthes', 'Excretion and osmoregulation in flatworms are done by', 'flame cells', ['nephridia', 'Malpighian tubules', 'proboscis gland'], 'Specialised flame cells (protonephridia) do this in flatworms. Nephridia are in annelids and Malpighian tubules in arthropods.');
mc(2, 'phylum Aschelminthes', '<i>Wuchereria</i>, the cause of filariasis, belongs to', 'Aschelminthes', ['Platyhelminthes', 'Annelida', 'Mollusca'], 'It is a roundworm (filaria worm). Other roundworms are <i>Ascaris</i> and <i>Ancylostoma</i> (hookworm).');
mc(2, 'phylum Aschelminthes', 'Roundworms differ from flatworms in having', 'a complete alimentary canal with a muscular pharynx', ['an incomplete gut with a single opening', 'an acoelomate condition', 'sexes that are not separate'], 'Aschelminthes have a mouth and an anus. They are dioecious, and the female is often longer than the male.');
mc(2, 'phylum Annelida', 'Lateral appendages that help <i>Nereis</i> to swim are', 'parapodia', ['pinnae', 'pedicellariae', 'tube feet'], 'Parapodia are paired fleshy outgrowths of aquatic annelids. Tube feet belong to echinoderms.');
mc(2, 'phylum Annelida', 'Which pair of annelids is monoecious?', 'Earthworm and leech', ['<i>Nereis</i> and earthworm', '<i>Nereis</i> and leech', '<i>Nereis</i> only'], '<i>Nereis</i> is dioecious, but earthworms and leeches are monoecious.');
mc(2, 'phylum Arthropoda', 'Excretory organs of arthropods are', 'Malpighian tubules', ['flame cells', 'nephridia', 'green glands in all of them'], 'Insects have Malpighian tubules. Do not confuse with nephridia of annelids.');
mc(2, 'phylum Arthropoda', 'Which of the following is NOT an arthropod?', '<i>Pila</i>', ['<i>Apis</i>', '<i>Limulus</i>', '<i>Locusta</i>'], '<i>Pila</i> is the apple snail, a mollusc. <i>Limulus</i> is the king crab, an arthropod known as a living fossil.');
mc(2, 'phylum Arthropoda', '<i>Laccifer</i>, <i>Bombyx</i> and <i>Apis</i> are economically important for', 'lac, silk and honey', ['silk, lac and honey', 'honey, silk and lac', 'pearl, silk and honey'], 'Laccifer gives lac, Bombyx (silkworm) gives silk and Apis (honeybee) gives honey.');
mc(2, 'phylum Arthropoda', 'Vectors of disease among insects include', '<i>Anopheles</i>, <i>Culex</i> and <i>Aedes</i>', ['<i>Apis</i>, <i>Bombyx</i> and <i>Locusta</i>', '<i>Limulus</i>, <i>Pila</i> and <i>Apis</i>', '<i>Locusta</i>, <i>Laccifer</i> and <i>Culex</i>'], 'These mosquitoes carry malaria, filariasis and dengue. <i>Locusta</i> is a gregarious pest.');
mc(2, 'phylum Mollusca', 'The space between the visceral hump and the mantle of a mollusc is the', 'mantle cavity, which has feather-like gills', ['coelom, which has the heart', 'pseudocoel, which holds the radula', 'spongocoel, which holds choanocytes'], 'The gills in the mantle cavity do respiration and excretion.');
mc(2, 'phylum Echinodermata', 'Adult echinoderms are ______ symmetrical and their larvae are ______ symmetrical.', 'radially, bilaterally', ['bilaterally, radially', 'radially, radially', 'bilaterally, bilaterally'], 'NCERT states the adults are radial and the larvae bilateral.');
mc(2, 'phylum Hemichordata', 'The body of <i>Balanoglossus</i> has', 'proboscis, collar and trunk', ['head, thorax and abdomen', 'foot, seta and capsule', 'visceral hump, foot and head'], 'Hemichordates are worm-like marine animals with these three parts; the proboscis gland does excretion.');
mc(2, 'Urochordata', 'In Urochordata the notochord is present', 'only in the larval tail', ['throughout the body for life', 'only in the head', 'not at all'], '<i>Ascidia</i>, <i>Salpa</i> and <i>Doliolum</i> have the notochord only in the larva. In Cephalochordata it stays from head to tail through life.');
mc(2, 'Cyclostomata', 'Cyclostomes have', 'circular mouth without jaws and 6 to 15 pairs of gill slits', ['jaws and an operculum', 'placoid scales and paired fins', 'a bony skull and swim bladder'], 'Petromyzon and Myxine have a sucking, jawless mouth. They have no scales or paired fins.');
mc(2, 'Chondrichthyes', 'Which feature does NOT belong to Chondrichthyes?', 'Air bladder', ['Placoid scales', 'Gill slits without operculum', 'Ventral mouth'], 'Cartilaginous fish have no air bladder, so they must keep swimming to avoid sinking.');
mc(2, 'Osteichthyes', 'In bony fishes, gills are covered by', 'an operculum', ['a mantle', 'a carapace', 'pinnae'], 'Osteichthyes have four pairs of gills covered by the operculum, an air bladder and a two-chambered heart.');
mc(2, 'Amphibia', 'The amphibian heart is', 'three-chambered, with two auricles and one ventricle', ['two-chambered', 'four-chambered', 'three-chambered, with one auricle and two ventricles'], 'Frogs have two auricles and one ventricle.');
mc(2, 'Reptilia', 'The skin of reptiles is', 'dry and cornified with epidermal scales or scutes', ['moist and without scales', 'covered with hair', 'covered with placoid scales only'], 'Reptiles creep or crawl and have dry skin. Snakes and lizards shed their scales as skin cast.');
mc(2, 'Aves', 'Birds have additional digestive chambers called', 'crop and gizzard', ['rumen and omasum', 'cloaca and caecum', 'crop and rumen'], 'The crop stores food and the gizzard grinds it.');
mc(2, 'Mammalia', 'Which mammal lays eggs?', '<i>Ornithorhynchus</i>', ['<i>Macropus</i>', '<i>Pteropus</i>', '<i>Camelus</i>'], 'The platypus is an egg-laying mammal. NCERT says most mammals are viviparous, with few exceptions.');
mc(2, 'Chordata', 'Which of these is NOT a basic feature of all chordates at some stage?', 'Ventral solid nerve cord', ['Notochord', 'Dorsal hollow nerve cord', 'Paired pharyngeal gill slits'], 'Chordates have a dorsal, hollow, single nerve cord. Non-chordates have a ventral, solid, double nerve cord.');

// ---------------------------------------------------------------- Level 3
asr(3, 'levels of organisation', 'Sponges are said to be at the cellular level of organisation.', 'Their cells do not form true tissues.', 0, 'Sponge cells are loosely arranged with some division of labour but there are no tissues. R explains A.');
asr(3, 'symmetry', 'Adult starfish are triploblastic even though they are radially symmetrical.', 'Radial symmetry occurs only in diploblastic animals.', 2, 'A is true: echinoderms are triploblastic with a coelom. R is false: radial symmetry occurs in some triploblastic animals, such as adult echinoderms.', 'Radial symmetry does not mean diploblastic.');
asr(3, 'Aves', 'Birds have pneumatic bones.', 'Long bones with air cavities reduce body weight for flight.', 0, 'NCERT says the long bones of birds are hollow with air cavities. This lightness helps flight.');
asr(3, 'Cyclostomata', 'Cyclostomes are classed separately from the group Pisces.', 'They lack jaws, whereas Pisces belong to Gnathostomata.', 0, 'Pisces are jawed vertebrates (Gnathostomata). Lamprey and hagfish are jawless and form class Cyclostomata.');
asr(3, 'Reptilia', 'Crocodiles have a four-chambered heart although they are reptiles.', 'Crocodiles are warm-blooded.', 2, 'A is true: most reptiles have three chambers, but crocodiles have four. R is false: all reptiles are cold-blooded (poikilothermous).', 'Four-chambered heart does not make them warm-blooded.');
asr(3, 'phylum Platyhelminthes', 'Parasitic flatworms have hooks and suckers.', 'These help them stay attached to the host.', 0, 'Hooks and suckers in <i>Taenia</i> and <i>Fasciola</i> help attachment.');
asr(4, 'phylum Ctenophora', 'Ctenophores are not placed in the phylum Cnidaria.', 'Ctenophores lack cnidoblasts and have comb plates.', 0, 'Both are diploblastic with tissue-level organisation, but ctenophores have eight rows of comb plates, colloblasts instead of cnidoblasts and reproduce only sexually.');
asr(4, 'phylum Hemichordata', 'Hemichordates are placed outside the phylum Chordata.', 'They have a true notochord and a dorsal hollow nerve cord.', 2, 'A is true: Hemichordata is now a separate phylum. R is false: they have no true notochord; the proboscis, collar and trunk body plan is different.', 'The old textbooks placed them in Chordata.');
stm(3, 'phylum Aschelminthes', 'Aschelminthes have a complete alimentary canal.', 'Platyhelminthes have an anus.', 2, 'Roundworms have mouth and anus. Flatworms have an incomplete gut with a single opening, so no anus. II is incorrect.');
stm(3, 'Chordata', 'All chordates are vertebrates.', 'All vertebrates are chordates.', 3, 'Urochordata and Cephalochordata are chordates without a vertebral column. So I is wrong and II is right because vertebrates have a notochord at some stage.', 'The reverse statement is always the trap.');
stm(3, 'circulation', 'Annelids have an open circulatory system.', 'Arthropods have a closed circulatory system.', 1, 'Annelids have closed circulation and arthropods have open circulation. Both statements are incorrect.');
stm(3, 'phylum Cnidaria', 'Cnidarians digest food only extracellularly.', 'They have a gastro-vascular cavity with a single opening.', 3, 'Digestion in cnidarians is both extracellular and intracellular. II is correct.');
stm(3, 'phylum Arthropoda', 'Mollusca is the second largest phylum.', 'More than two-thirds of the named animal species are arthropods.', 0, 'Both are as in NCERT.');
stm(3, 'fishes', 'In Chondrichthyes fertilisation is internal and many are viviparous.', 'In Osteichthyes fertilisation is usually external and they are mostly oviparous.', 0, 'Sharks and rays have internal fertilisation; bony fishes shed eggs and sperm in water.');
stm(4, 'Amphibia and Reptilia', 'Amphibians have internal fertilisation.', 'Reptiles have internal fertilisation.', 3, 'Frogs have external fertilisation. Reptiles have internal fertilisation and are oviparous.');
stm(4, 'Cyclostomata', 'Lampreys and hagfishes are marine but migrate to fresh water to spawn.', 'After spawning, the adults live for many years.', 2, 'NCERT says they die within a few days after spawning, and the larvae return to the ocean after metamorphosis.');
stm(4, 'Mammalia', 'The heart of all mammals is four-chambered.', 'All mammals are viviparous.', 2, 'Four chambers hold for all. A few mammals, like the platypus, lay eggs, so II is wrong.');

match(2, 'examples', 'am1', 'Animal and phylum', ['A. <i>Euspongia</i>', 'B. <i>Meandrina</i>', 'C. <i>Dentalium</i>', 'D. <i>Antedon</i>'], ['p. Echinodermata', 'q. Porifera', 'r. Cnidaria', 's. Mollusca'], 'A-q, B-r, C-s, D-p', ['A-q, B-r, C-p, D-s', 'A-r, B-q, C-s, D-p', 'A-s, B-r, C-q, D-p'], 'Bath sponge is a poriferan; brain coral is a cnidarian; tusk shell is a mollusc; sea lily is an echinoderm.');
match(3, 'excretory organs', 'am2', 'Phylum and excretory structure', ['A. Platyhelminthes', 'B. Annelida', 'C. Arthropoda', 'D. Hemichordata'], ['p. Nephridia', 'q. Malpighian tubules', 'r. Flame cells', 's. Proboscis gland'], 'A-r, B-p, C-q, D-s', ['A-p, B-r, C-q, D-s', 'A-r, B-p, C-s, D-q', 'A-q, B-p, C-r, D-s'], 'Flame cells in flatworms, nephridia in annelids, Malpighian tubules in arthropods, proboscis gland in hemichordates.');
match(3, 'classes of chordates', 'am3', 'Class and feature', ['A. Chondrichthyes', 'B. Osteichthyes', 'C. Aves', 'D. Mammalia'], ['p. Gills covered by operculum', 'q. Placoid scales', 'r. Crop and gizzard', 's. Pinnae and hair'], 'A-q, B-p, C-r, D-s', ['A-p, B-q, C-r, D-s', 'A-q, B-p, C-s, D-r', 'A-q, B-r, C-p, D-s'], 'Sharks have placoid scales, bony fishes an operculum, birds a crop and gizzard, mammals external ears and hair.');
match(3, 'common names', 'am4', 'Genus and common name', ['A. <i>Pila</i>', 'B. <i>Loligo</i>', 'C. <i>Hirudinaria</i>', 'D. <i>Limulus</i>'], ['p. King crab', 'q. Squid', 'r. Blood sucking leech', 's. Apple snail'], 'A-s, B-q, C-r, D-p', ['A-q, B-s, C-r, D-p', 'A-s, B-q, C-p, D-r', 'A-r, B-q, C-s, D-p'], 'Pila is the apple snail, Loligo the squid, Hirudinaria the leech, Limulus the king crab.');
match(4, 'common names', 'am5', 'Genus and common name', ['A. <i>Physalia</i>', 'B. <i>Pennatula</i>', 'C. <i>Gorgonia</i>', 'D. <i>Adamsia</i>'], ['p. Sea anemone', 'q. Sea fan', 'r. Portuguese man-of-war', 's. Sea pen'], 'A-r, B-s, C-q, D-p', ['A-s, B-r, C-q, D-p', 'A-r, B-s, C-p, D-q', 'A-q, B-s, C-r, D-p'], 'Physalia is the Portuguese man-of-war, Pennatula the sea pen, Gorgonia the sea fan and Adamsia the sea anemone, all cnidarians.');

mc(3, 'trick pairs', 'Which one of these is a true fish?', 'Flying fish (<i>Exocoetus</i>)', ['Jellyfish (<i>Aurelia</i>)', 'Cuttlefish (<i>Sepia</i>)', 'Starfish (<i>Asterias</i>)'], 'The jelly fish is a cnidarian, the cuttlefish a mollusc, the starfish an echinoderm. <i>Exocoetus</i> is a bony fish.', 'The word fish in a common name does not guarantee a fish.');
mc(3, 'trick pairs', 'Devil fish (<i>Octopus</i>) belongs to', 'Mollusca', ['Osteichthyes', 'Chondrichthyes', 'Cnidaria'], 'Octopus is a cephalopod mollusc, not a fish.', 'The name is misleading.');
mc(3, 'trick pairs', 'The sea horse <i>Hippocampus</i> is', 'a bony fish', ['a mollusc', 'an amphibian', 'a cartilaginous fish'], 'Sea horse is a marine member of Osteichthyes, although it does not look like a typical fish.');
mc(3, 'trick pairs', 'The animal with a body plan that is NOT a vertebrate among the following is', 'Sea cucumber', ['Sea horse', 'Flying fox', 'Flying fish'], 'Sea cucumber (<i>Cucumaria</i>) is an echinoderm. The flying fox (<i>Pteropus</i>) is a mammal and flying fish is a bony fish.', 'Flying fox is a bat, not a fox.');
mc(3, 'Cephalochordata', 'Which of the following is true of <i>Branchiostoma</i>?', 'It is a marine chordate with a notochord from head to tail', ['It has a notochord only in the larval tail', 'It is a vertebrate with a skull', 'It is a hemichordate'], 'It belongs to Cephalochordata. Larval-tail-only notochord is Urochordata.');
mc(3, 'phylum Mollusca', 'Which pair is correctly matched?', '<i>Pinctada</i> – pearl oyster', ['<i>Sepia</i> – seahare', '<i>Aplysia</i> – cuttlefish', '<i>Chaetopleura</i> – squid'], '<i>Sepia</i> is the cuttlefish, <i>Aplysia</i> the seahare and <i>Chaetopleura</i> the chiton.');
mc(3, 'phylum Echinodermata', 'Which of the following has water vascular system and a larva with bilateral symmetry?', '<i>Asterias</i>', ['<i>Aurelia</i>', '<i>Balanoglossus</i>', '<i>Pheretima</i>'], 'Starfish is an echinoderm: radial adults, bilateral larvae.');
mc(3, 'phylum Echinodermata', 'Which of these is absent in echinoderms?', 'Excretory system', ['Complete digestive system', 'Coelom', 'Water vascular system'], 'NCERT says an excretory system is absent. The mouth is ventral and the anus dorsal.');
mc(3, 'Pisces', 'Air bladder is present in', 'Osteichthyes', ['Chondrichthyes', 'Cyclostomata', 'Both Chondrichthyes and Cyclostomata'], 'Air bladder regulates buoyancy in bony fishes. Sharks lack it and sink if they stop swimming.');
mc(3, 'Pisces', 'Which fish is cartilaginous?', '<i>Trygon</i> (sting ray)', ['<i>Labeo</i>', '<i>Catla</i>', '<i>Clarias</i>'], 'Sting ray is Chondrichthyes with poison sting. Rohu, katla and magur are bony fishes.');
mc(3, 'Pisces', 'A fish with an electric organ, belonging to Chondrichthyes, is', '<i>Torpedo</i>', ['<i>Pterophyllum</i>', '<i>Betta</i>', '<i>Hippocampus</i>'], 'The other three are bony fishes.');
mc(3, 'Pisces', 'Which of these are aquarium fishes?', '<i>Betta</i> and <i>Pterophyllum</i>', ['<i>Labeo</i> and <i>Catla</i>', '<i>Exocoetus</i> and <i>Clarias</i>', '<i>Scoliodon</i> and <i>Pristis</i>'], 'Fighting fish and angel fish are common aquarium fishes. Labeo and Catla are edible freshwater fishes.');
mc(3, 'Amphibia', '<i>Ichthyophis</i> is', 'a limbless amphibian', ['a limbless reptile', 'a bony fish', 'a cyclostome'], 'It is a limbless amphibian (caecilian). Many assume limbless means snake.');
mc(3, 'Amphibia', 'In frogs, the alimentary canal, urinary and reproductive ducts open into', 'the cloaca', ['the bladder', 'the pharynx', 'the cecum'], 'The cloaca opens to the outside.');
mc(3, 'Reptilia', 'The poisonous snakes among these are', '<i>Naja</i>, <i>Bangarus</i> and <i>Vipera</i>', ['<i>Naja</i>, <i>Calotes</i> and <i>Hemidactylus</i>', '<i>Chelone</i>, <i>Testudo</i> and <i>Naja</i>', '<i>Calotes</i>, <i>Chameleon</i> and <i>Vipera</i>'], 'Cobra, krait and viper are poisonous. Calotes, Chameleon and Hemidactylus are lizards; Chelone and Testudo are chelonians.');
mc(3, 'Aves', 'The only gland found in the skin of birds is', 'the oil gland at the base of the tail', ['sweat gland', 'mammary gland', 'sebaceous gland on wings'], 'Bird skin is dry without glands except the oil gland.');
mc(3, 'Aves', 'Air sacs of birds are', 'connected to lungs and supplement respiration', ['part of the gizzard', 'part of the crop', 'filled with hydrogen to lighten the body'], 'Lungs plus air sacs allow a one-way flow of air.');
mc(3, 'Mammalia', 'Which of the following mammals is a flying mammal?', '<i>Pteropus</i>', ['<i>Macropus</i>', '<i>Camelus</i>', '<i>Equus</i>'], 'Pteropus is the flying fox (a bat). Macropus is the kangaroo, Camelus the camel and Equus the horse.');
mc(3, 'Mammalia', 'Aquatic mammals among these are', '<i>Delphinus</i> and <i>Balaenoptera</i>', ['<i>Pteropus</i> and <i>Macaca</i>', '<i>Macropus</i> and <i>Rattus</i>', '<i>Felis</i> and <i>Canis</i>'], 'Dolphin and blue whale are aquatic mammals. They breathe air through lungs, not gills.');
mc(3, 'Mammalia', 'Cat, dog and monkey genera in order are', '<i>Felis</i>, <i>Canis</i>, <i>Macaca</i>', ['<i>Canis</i>, <i>Felis</i>, <i>Macaca</i>', '<i>Felis</i>, <i>Macaca</i>, <i>Canis</i>', '<i>Macaca</i>, <i>Canis</i>, <i>Felis</i>'], 'Cat is <i>Felis</i>, dog <i>Canis</i>, monkey <i>Macaca</i>.');
mc(3, 'Aves', 'The flightless bird among these is', '<i>Struthio</i>', ['<i>Columba</i>', '<i>Corvus</i>', '<i>Psittacula</i>'], 'Ostrich (<i>Struthio</i>) cannot fly. Pigeon, crow and parrot can.');
mc(3, 'Reptilia', '<i>Chelone</i> and <i>Testudo</i> are', 'turtle and tortoise', ['crocodile and alligator', 'cobra and krait', 'garden lizard and chameleon'], 'These are chelonian reptiles.');

// ---------------------------------------------------------------- Level 4
mc(4, 'levels of organisation', 'Which phylum shows the organ level of organisation (not the organ-system level)?', 'Platyhelminthes', ['Cnidaria', 'Annelida', 'Porifera'], 'Flatworms have organs but no organ systems. Cnidaria is tissue level, Porifera cellular, and Annelida organ-system level.', 'Organ and organ-system level are separate steps.');
mc(4, 'germ layers', 'Which of the following are diploblastic?', 'Cnidaria and Ctenophora', ['Porifera and Platyhelminthes', 'Aschelminthes and Annelida', 'Echinodermata and Hemichordata'], 'Both Cnidaria and Ctenophora have ectoderm, endoderm and a mesoglea. All the rest of the groups listed from Platyhelminthes onwards are triploblastic.');
mc(4, 'coelom', 'Arrange the groups in order of body cavity: acoelomate, pseudocoelomate, coelomate.', 'Taenia, Ascaris, Pheretima', ['Ascaris, Taenia, Pheretima', 'Pheretima, Ascaris, Taenia', 'Taenia, Pheretima, Ascaris'], 'Taenia has no cavity, Ascaris a pseudocoelom lined partly by mesoderm, Pheretima a true coelom.');
mc(4, 'digestion', 'Choose the group with incomplete digestive system.', 'Platyhelminthes', ['Aschelminthes', 'Annelida', 'Echinodermata'], 'Flatworms and cnidarians have a single opening to the gut. All three others have a mouth and an anus.');
mc(4, 'circulation', 'Which phylum has an open circulatory system and a coelom?', 'Mollusca', ['Annelida', 'Chordata in general', 'Aschelminthes'], 'Molluscs and arthropods are coelomate with open circulation. Annelids and chordates have closed circulation, and aschelminths are pseudocoelomate.');
mc(4, 'symmetry', 'How many of these are radially symmetrical as adults: sea anemone, comb jelly, starfish, sponge, earthworm?', 'Three', ['Two', 'Four', 'Five'], 'Sea anemone (Cnidaria), comb jelly (Ctenophora) and starfish (Echinodermata) are radial. Sponges are mostly asymmetrical, and the earthworm is bilateral.', 'Starfish is radial as an adult only; its larva is bilateral.');
mc(4, 'phylum Arthropoda', 'Respiratory organs in arthropods are', 'gills, book gills, book lungs or tracheae', ['gills only', 'lungs only', 'parapodia and gills only'], 'Prawns have gills, king crabs book gills, spiders and scorpions book lungs and insects tracheae.');
mc(4, 'phylum Arthropoda', '<i>Limulus</i> is called a living fossil because', 'it has changed little over a very long time and is an arthropod', ['it is a cnidarian that lives in rocks', 'it is the only arthropod without legs', 'it lacks a coelom'], 'NCERT lists it as a living fossil, a king crab with book gills.');
mc(4, 'phylum Mollusca', 'Choose the incorrect statement about Mollusca.', 'Body is metamerically segmented with parapodia', ['Body is soft and covered by a calcareous shell', 'Radula is present in mouth', 'They are usually dioecious and oviparous'], 'Molluscs are unsegmented. Segmentation and parapodia belong to annelids like Nereis.');
mc(4, 'phylum Annelida', 'Nervous system of Annelida has', 'paired ganglia, lateral nerves and a double ventral nerve cord', ['a dorsal hollow nerve cord', 'a nerve net only', 'a single ventral cord with no ganglia'], 'Annelids have a ventral solid double nerve cord.');
mc(4, 'phylum Echinodermata', 'In echinoderms, the mouth and anus are placed', 'ventral and dorsal respectively', ['dorsal and ventral', 'both at the posterior end', 'on the same side'], 'NCERT: mouth on the ventral side and anus on the dorsal side.');
mc(4, 'phylum Hemichordata', 'Which character is common to Hemichordata and Chordata?', 'Pharyngeal gill slits in some members, bilateral symmetry and a coelom', ['Dorsal hollow nerve cord', 'Notochord in the adult', 'Post-anal tail'], 'Both are bilateral, triploblastic and coelomate, and respiratory gills are used. A dorsal hollow nerve cord and notochord are not there in hemichordates.');
mc(4, 'Chondrichthyes', 'Which description fits a shark?', 'Ventral mouth, placoid scales, no operculum, heart two-chambered', ['Terminal mouth, cycloid scales, operculum, air bladder', 'Ventral mouth, cycloid scales, air bladder, three-chambered heart', 'Terminal mouth, placoid scales, operculum, no air bladder'], 'Sharks are Chondrichthyes: ventral mouth, tough skin with placoid scales, separate gill slits and a two-chambered heart.');
mc(4, 'Pisces', 'The heart of fishes is two-chambered. It receives and pumps', 'deoxygenated blood only', ['oxygenated blood only', 'mixed blood', 'blood pumped to lungs only'], 'The two chambers are one auricle and one ventricle, with deoxygenated blood sent to gills.');
mc(4, 'Amphibia', 'A tympanum, eyelids and moist skin without scales are present in', '<i>Rana</i>', ['<i>Calotes</i>', '<i>Scoliodon</i>', '<i>Petromyzon</i>'], 'Rana is an amphibian. Calotes (a reptile) has a dry skin with scales.');
mc(4, 'Reptilia', 'Which of these is correct about reptiles?', 'The tympanum represents the ear and sexes are separate with internal fertilisation', ['They have external ears (pinnae)', 'They give birth only to live young', 'They have moist skin without scales'], 'Pinnae are a mammalian feature.');
mc(4, 'Chordata', 'Which has a post-anal tail at some stage?', 'Chordates', ['All non-chordates', 'Only birds', 'Only fish'], 'A post-anal tail, a notochord and a dorsal nerve cord are chordate features.');
mc(4, 'Chordata', 'In Vertebrata the notochord is', 'replaced by the vertebral column in the adult', ['present only in the head', 'absent in the embryo', 'replaced by a skull'], 'The embryo has a notochord, and the cartilaginous or bony vertebral column replaces it.');

// ---------------------------------------------------------------- Level 5
mc(5, 'mixed statements', 'How many are correct? (i) Ctenophores reproduce only sexually. (ii) Cnidarian polyps are free-swimming. (iii) Sponges have a mouth. (iv) Flatworms are acoelomate.', 'Two', ['One', 'Three', 'Four'], '(i) and (iv) are correct. Polyps are sessile, medusae free-swimming; sponges have only an osculum and ostia.', 'Count carefully.');
mc(5, 'mixed statements', 'Which of the following animals have BOTH an open circulatory system and jointed appendages?', 'Prawn, locust and scorpion', ['Earthworm, locust and prawn', 'Snail, earthworm and prawn', 'Star fish, locust and scorpion'], 'Arthropods have jointed appendages and open circulation. Earthworm has closed circulation, snail has no jointed legs and starfish has no jointed appendages.');
mc(5, 'mixed statements', 'Choose the sequence in order of increasing complexity of level of organisation: sponge, jelly fish, tapeworm, earthworm.', 'Sponge, jelly fish, tapeworm, earthworm', ['Jelly fish, sponge, tapeworm, earthworm', 'Sponge, tapeworm, jelly fish, earthworm', 'Tapeworm, sponge, earthworm, jelly fish'], 'Cellular (sponge), tissue (jelly fish), organ (tapeworm), organ system (earthworm).');
mc(5, 'mixed statements', 'Which is the only characteristic common to ALL of cyclostomes, sharks, frogs and birds?', 'Presence of a notochord at least in the embryo and gill slits at some stage', ['Jaws', 'Paired fins', 'Scales'], 'All are chordates; but jaws and paired appendages are missing in cyclostomes, and fins are absent in frogs and birds.');
mc(5, 'mixed statements', 'A marine animal is triploblastic, coelomate, radially symmetric as adult, has calcareous ossicles and no excretory organs. It is', 'a sea urchin', ['a sea anemone', 'a sea walnut', 'a cuttlefish'], 'Echinoderm features. Anemone and sea walnut are diploblastic; cuttlefish is bilateral with a shell.');
mc(5, 'mixed statements', 'Which of the following is NOT a feature of both Aves and Mammalia?', 'Presence of feathers', ['Four-chambered heart', 'Homoiothermy', 'Internal fertilisation'], 'Feathers are only in birds. All the rest are shared.');
mc(5, 'mixed statements', 'Which one of the following pairs of animals both have a three-chambered heart?', 'Frog and lizard', ['Frog and crocodile', 'Fish and frog', 'Lizard and pigeon'], 'Amphibia and most reptiles have three chambers; crocodile has four, fishes two, pigeon four.');
mc(5, 'mixed statements', 'Total classes among <i>Scoliodon</i>, <i>Labeo</i>, <i>Rana</i>, <i>Calotes</i>, <i>Corvus</i>, <i>Canis</i>, <i>Petromyzon</i> are', '7', ['6', '5', '4'], 'Chondrichthyes, Osteichthyes, Amphibia, Reptilia, Aves, Mammalia, Cyclostomata: seven different classes.');
mc(5, 'phylum Ctenophora', 'Which statement about a ctenophore is correct?', 'Fertilisation is external and development is indirect', ['Fertilisation is internal and development is direct', 'Reproduction is by budding and fragmentation', 'Sexes are separate'], 'Ctenophores are hermaphrodite and fertilise externally. Reproduction is only sexual.');
mc(5, 'phylum Aschelminthes', 'Which statement is wrong about a roundworm?', 'It is acoelomate with a blind gut', ['Body is circular in cross-section', 'Sexes are separate', 'Excretory tube opens by a pore'], 'Roundworms are pseudocoelomates with a complete gut.');

pass('ap1', 'Passage: a mystery specimen', 'A specimen has a soft, unsegmented body with a muscular foot and a visceral hump covered by a fold of skin. A calcareous shell covers it. Between the hump and the fold lie feather-like structures. The mouth contains a file-like organ. The sexes are separate and development is indirect.');
pq('ap1', 3, 'phylum Mollusca', 'The animal belongs to', 'Mollusca', ['Annelida', 'Echinodermata', 'Arthropoda'], 'The foot, mantle, shell and radula identify a mollusc.');
pq('ap1', 3, 'phylum Mollusca', 'The feather-like structures are', 'gills in the mantle cavity', ['book lungs', 'tube feet', 'parapodia'], 'The mantle cavity holds feather-like gills that do respiration and excretion.');
pq('ap1', 4, 'phylum Mollusca', 'The file-like organ and the animal could be', 'radula in <i>Pila</i>', ['nematocyst in <i>Pila</i>', 'radula in <i>Asterias</i>', 'proboscis in <i>Octopus</i>'], 'The apple snail <i>Pila</i> is a mollusc with a radula. Octopus has a radula too, but not a proboscis. Asterias is not a mollusc.');
pass('ap2', 'Passage: five chordates', 'Five animals are examined: P has dry skin with scales and a three-chambered heart; Q has hollow bones and a crop; R has a jawless circular mouth with gill slits; S has hair and a four-chambered heart; T has a cartilaginous skeleton, placoid scales and a ventral mouth.');
pq('ap2', 3, 'Chordata', 'Animal R belongs to the class', 'Cyclostomata', ['Chondrichthyes', 'Amphibia', 'Osteichthyes'], 'Jawless, circular mouth and 6 to 15 pairs of gill slits show a cyclostome like Petromyzon.');
pq('ap2', 3, 'Chordata', 'Animals P, Q and S are respectively', 'reptile, bird, mammal', ['amphibian, bird, mammal', 'reptile, mammal, bird', 'bird, reptile, mammal'], 'P: dry scaly skin and a three-chambered heart point to a reptile. Q: pneumatic bones and crop point to a bird. S: hair points to a mammal.');
pq('ap2', 4, 'Chordata', 'T could be', '<i>Scoliodon</i>', ['<i>Labeo</i>', '<i>Hippocampus</i>', '<i>Myxine</i>'], 'A cartilaginous skeleton with placoid scales is Chondrichthyes. The others are bony fishes and a hagfish.');

// ---------------------------------------------------------------- Expansion (added 2026-11-22)
// ---- Level 2
mc(2, 'porifera', 'The pores through which water enters the body of a sponge are called', 'ostia', ['osculum', 'cnidocils', 'spiracles'], 'Water enters through many ostia and leaves through the osculum.', 'Osculum is the large exit opening.');
mc(2, 'porifera', 'The skeleton of sponges is made of', 'spicules or spongin fibres', ['chitin', 'calcium carbonate shell', 'bone'], 'Sponges have a skeleton of spicules or spongin fibres.');
mc(2, 'porifera', 'Which of these is a freshwater sponge?', 'Spongilla', ['Sycon', 'Euspongia', 'Obelia'], 'Spongilla lives in fresh water. Sycon and Euspongia are marine.');
mc(2, 'cnidaria', 'Stinging cells of cnidarians are called', 'cnidoblasts', ['choanocytes', 'flame cells', 'comb plates'], 'Cnidoblasts (cnidocytes) hold nematocysts used for anchorage, defence and capture of prey.');
mc(2, 'cnidaria', 'Which of these is a medusa form?', 'Aurelia', ['Hydra', 'Adamsia', 'Pennatula'], 'Aurelia (jelly fish) is free-swimming and umbrella-shaped. Hydra and Adamsia are polyps.');
mc(2, 'platyhelminthes', 'Which of these is a flatworm?', 'Fasciola', ['Ascaris', 'Nereis', 'Pila'], 'Fasciola (liver fluke) is a trematode flatworm.');
mc(2, 'mollusca', 'The rasping organ of molluscs that helps in feeding is the', 'radula', ['mantle', 'foot', 'tympanum'], 'Radula is a file-like organ in the mouth cavity.');
mc(2, 'echinodermata', 'Which of the following is an echinoderm?', 'Asterias', ['Aplysia', 'Pheretima', 'Ascidia'], 'Asterias (star fish) belongs to Echinodermata.');
mc(2, 'chordata', 'The notochord of adult Branchiostoma', 'extends from head to tail and persists throughout life', ['is present only in the larval tail', 'is replaced by a vertebral column', 'is absent'], 'Cephalochordates keep a notochord through life.');
mc(2, 'aves', 'The only gland in the skin of most birds is the', 'oil gland at the base of the tail', ['sweat gland', 'mammary gland', 'sebaceous gland on the wing'], 'Feathers are kept oiled by this gland.');
mc(2, 'mammalia', 'Which of the following is a marsupial that carries its young in a pouch?', 'Macropus', ['Pteropus', 'Delphinus', 'Elephas'], 'Macropus is the kangaroo. Pteropus is a flying fox.');
mc(2, 'reptilia', 'The three-chambered heart of reptiles becomes four-chambered in', 'crocodiles', ['snakes', 'turtles', 'lizards'], 'Crocodilus is the exception.');

// ---- Level 3
mc(3, 'basis', 'In which type of symmetry can an animal be divided into two equal halves in only one plane?', 'Bilateral symmetry', ['Radial symmetry', 'Asymmetry', 'Spherical symmetry'], 'Annelids, arthropods and chordates show bilateral symmetry.');
mc(3, 'basis', 'Tissue level of organisation is the highest level shown by', 'Cnidaria', ['Porifera', 'Platyhelminthes', 'Annelida'], 'Cnidaria and Ctenophora show the tissue level. Porifera is cellular; Platyhelminthes is organ level.');
mc(3, 'basis', 'Animals whose germ layers are ectoderm and endoderm only, with mesoglea in between, are', 'diploblastic', ['triploblastic', 'acoelomate', 'metameric'], 'Mesoglea is non-cellular or has scattered cells.');
mc(3, 'basis', 'The coelom is lined by', 'mesoderm', ['ectoderm', 'endoderm', 'none of the germ layers'], 'A true coelom is a body cavity lined by mesoderm.');
mc(3, 'porifera', 'Digestion in sponges is', 'intracellular', ['extracellular only', 'both inside and outside the body', 'absent'], 'Food is digested inside choanocytes and amoebocytes.');
mc(3, 'porifera', 'In sponges, fertilisation is', 'internal, with free-swimming larvae', ['external, with no larva', 'internal, with direct development', 'absent, only budding'], 'Sponges are hermaphrodite (bisexual), fertilisation is internal and development is indirect.');
mc(3, 'cnidaria', 'Hydra shows which form of body?', 'Polyp, sessile and cylindrical', ['Medusa, free swimming', 'Alternating polyp and medusa', 'Larval form only'], 'Hydra is a polyp. Obelia has both.');
mc(3, 'cnidaria', 'Which of the following is a coral?', 'Meandrina', ['Physalia', 'Adamsia', 'Aurelia'], 'Meandrina is the brain coral. Corals have a skeleton of calcium carbonate.');
mc(3, 'cnidaria', 'The central cavity of cnidarians opens to the outside by', 'a single opening, the mouth on the hypostome', ['an anus only', 'a pair of mouths', 'no opening'], 'The coelenteron has one opening.');
mc(3, 'ctenophora', 'Ctenophores are also called', 'sea walnuts or comb jellies', ['sea stars', 'sea pens', 'sea lilies'], 'They have eight external rows of ciliated comb plates.');
mc(3, 'ctenophora', 'Bioluminescence is well marked in', 'Ctenophora', ['Porifera', 'Platyhelminthes', 'Aves'], 'NCERT notes bioluminescence (the property of a living organism to emit light) is well-marked in ctenophores.');
mc(3, 'platyhelminthes', 'Flame cells of flatworms function in', 'osmoregulation and excretion', ['respiration', 'locomotion', 'digestion'], 'Flame cells remove excess water and wastes.');
mc(3, 'platyhelminthes', 'The remarkable power of regeneration is seen in', 'Planaria', ['Taenia', 'Fasciola', 'Ascaris'], 'Some flatworms like Planaria have high regeneration capacity.');
mc(3, 'aschelminthes', 'Which of the following is NOT an aschelminth?', 'Fasciola', ['Ascaris', 'Wuchereria', 'Ancylostoma'], 'Fasciola is a flatworm.');
mc(3, 'aschelminthes', 'In roundworms the sexes are', 'separate, with females usually longer than males', ['same in one individual', 'same with equal size', 'absent'], 'They are dioecious.');
mc(3, 'annelida', 'Which of these annelids is aquatic and dioecious?', 'Nereis', ['Pheretima', 'Hirudinaria', 'Taenia'], 'Nereis is dioecious. Earthworms and leeches are monoecious.');
mc(3, 'annelida', 'The blood-sucking leech belongs to the genus', 'Hirudinaria', ['Pheretima', 'Nereis', 'Aphis'], 'Hirudinaria is the Indian cattle leech.');
mc(3, 'arthropoda', 'The fraction of all named species that are arthropods is more than', 'two-thirds', ['one-tenth', 'one-half only', 'one-third'], 'NCERT: over two-thirds of all named species on earth are arthropods.');
mc(3, 'arthropoda', 'Compound eyes are an example of', 'sensory organs in arthropods', ['excretory organs', 'respiratory organs', 'reproductive organs'], 'Arthropods have antennae, compound and simple eyes and statocysts.');
mc(3, 'arthropoda', 'A gregarious pest among the following is', 'Locusta', ['Apis', 'Bombyx', 'Laccifer'], 'Locusta is the locust.');
mc(3, 'arthropoda', 'Book lungs are present in', 'scorpions', ['prawns', 'cockroach', 'butterflies'], 'Book lungs and book gills are found in some arthropods; scorpions and spiders have book lungs.');
mc(3, 'mollusca', 'The feather-like gills of molluscs lie in', 'the mantle cavity', ['the foot', 'the radula', 'the shell'], 'Gills function in respiration and excretion.');
mc(3, 'mollusca', 'Which of these is a mollusc?', 'Pinctada', ['Antedon', 'Limulus', 'Balanoglossus'], 'Pinctada is the pearl oyster.');
mc(3, 'echinodermata', 'Echinoderms have', 'an endoskeleton of calcareous ossicles', ['a chitinous exoskeleton', 'a shell of one piece', 'no skeleton'], 'The name means spiny skinned.');
mc(3, 'hemichordata', 'The body of Hemichordata is divided into', 'proboscis, collar and trunk', ['head, thorax and abdomen', 'head and visceral hump', 'oral and aboral sides'], 'It is worm-like with these three parts.');
mc(3, 'chordata', 'The post-anal tail of a chordate is', 'a part of the body extending beyond the anus', ['a tail in front of the anus', 'a part in the head', 'present only in birds'], 'It is one of the four features of chordates.');
mc(3, 'cyclostomata', 'Which feature belongs to cyclostomes?', 'Circular sucking mouth without jaws', ['Placoid scales', 'Operculum', 'Four-chambered heart'], 'Lamprey and hagfish are jawless.');
mc(3, 'chondrichthyes', 'The male sharks have claspers on', 'the pelvic fins', ['the pectoral fins', 'the tail fin', 'the gill slits'], 'Claspers help in internal fertilisation.');
mc(3, 'osteichthyes', 'Which fish is bony?', 'Catla', ['Trygon', 'Pristis', 'Carcharodon'], 'Catla is a freshwater bony fish. The others are cartilaginous.');
mc(3, 'amphibia', 'The heart of an adult frog has', 'two atria and one ventricle', ['one atrium and one ventricle', 'two atria and two ventricles', 'one atrium and two ventricles'], 'Three chambers.');
mc(3, 'reptilia', 'The reptile that is a limbed lizard is', 'Calotes', ['Naja', 'Bangarus', 'Vipera'], 'Naja, Bangarus and Vipera are snakes.');
mc(3, 'aves', 'The lungs of birds are supplemented by', 'air sacs', ['the gizzard', 'the crop', 'the cloaca'], 'The air sacs are connected to the lungs.');
mc(3, 'mammalia', 'Which mammal is oviparous?', 'Ornithorhynchus', ['Macropus', 'Pteropus', 'Elephas'], 'The platypus lays eggs.');

asr(2, 'porifera', 'Sponges are called animals even though they are sessile.', 'Sponges are multicellular and heterotrophic.', 0, 'Being multicellular and heterotrophic places them among animals.');
asr(3, 'cnidaria', 'Cnidarians catch prey with tentacles.', 'Tentacles carry cnidoblasts with nematocysts.', 0, 'Stinging capsules help to capture prey and for defence.');
asr(3, 'platyhelminthes', 'Flatworms are acoelomates.', 'They have a body cavity lined by mesoderm.', 2, 'A is true. R is false: acoelomates have no body cavity.');
asr(3, 'chordata', 'Urochordates are called tunicates.', 'Their body is covered by a tunic.', 0, 'The tunic gives the name tunicata.');
asr(4, 'arthropoda', 'Arthropods have an open circulatory system.', 'Blood flows in a closed system of vessels in arthropods.', 2, 'A is true. R is false: blood is pumped into body cavities (haemocoel) in an open system.');
asr(4, 'echinodermata', 'Adult echinoderms are radially symmetrical.', 'Echinoderm larvae are bilaterally symmetrical.', 1, 'Both are true, but the larval symmetry does not explain the adult symmetry.', 'Students often pick the first option because both are famous facts.');
asr(4, 'aves', 'Birds are called warm blooded.', 'Their body temperature stays constant regardless of the surroundings.', 0, 'Homoiothermy means a constant body temperature.');
asr(5, 'chondrichthyes', 'Sharks must keep swimming to avoid sinking.', 'Sharks lack an air bladder.', 0, 'With no air bladder, they keep up buoyancy by constant swimming.');
asr(5, 'mammalia', 'All mammals are viviparous.', 'Mammals have mammary glands.', 3, 'A is false: Ornithorhynchus lays eggs. R is true.');
asr(5, 'hemichordata', 'Hemichordates were once placed in the phylum Chordata but are now a separate phylum.', 'Hemichordates have a true notochord and a dorsal hollow nerve cord.', 2, 'A is true. R is false: they lack the chordate features, so they are now kept outside the Chordata.', 'The old placement does not mean they have the chordate features.');

stm(3, 'basis', 'Radial symmetry is found in Cnidaria.', 'Bilateral symmetry is found in Arthropoda.', 0, 'Both are correct.');
stm(3, 'porifera', 'Sponges have a water canal system.', 'Sponges show the organ-system level of organisation.', 2, 'II is false: it is cellular level.');
stm(3, 'platyhelminthes', 'Flatworms are dorsoventrally flattened.', 'Flatworms are pseudocoelomates.', 2, 'They are acoelomates.');
stm(4, 'annelida', 'Annelids show metameric segmentation.', 'Annelids are acoelomates.', 2, 'They are coelomates.');
stm(4, 'mollusca', 'Molluscs have a muscular foot.', 'Molluscs are segmented.', 2, 'Their body is unsegmented.');
stm(4, 'chordata', 'Vertebrates have a vertebral column.', 'All chordates have a vertebral column.', 2, 'Only vertebrates have it; urochordates and cephalochordates lack it.');
stm(4, 'aves', 'Birds have a pneumatic skeleton.', 'The birds have a two-chambered heart.', 2, 'The bird heart has four chambers.');
mc(4, 'basis', 'Consider: (i) Cnidaria are diploblastic. (ii) Platyhelminthes are triploblastic. (iii) Aschelminthes are acoelomate. (iv) Annelida are coelomate. How many are correct?', 'Three', ['Two', 'Four', 'One'], '(i), (ii), (iv) are right. Aschelminthes are pseudocoelomate.', 'Pseudocoelom is not the same as no coelom.', 'statements');
mc(4, 'chordata', 'Consider: (i) Frogs have external fertilisation. (ii) Lizards have internal fertilisation. (iii) Birds are oviparous. (iv) Whales are oviparous. How many are correct?', 'Three', ['Two', 'Four', 'One'], '(i), (ii), (iii) are correct. Whales are mammals and are viviparous.', null, 'statements');
mc(5, 'chordata', 'Consider: (i) Sharks have an air bladder. (ii) Bony fishes have an operculum. (iii) Amphibians have a cloaca. (iv) Reptiles have external ears. (v) Birds have a gizzard. How many are correct?', 'Three', ['Two', 'Four', 'Five'], '(ii), (iii), (v) are correct. Sharks lack an air bladder, and reptiles have no external ear openings (a tympanum represents the ear).', 'Air bladder and ear are the two false ones.', 'statements');
mc(5, 'basis', 'Consider: (i) Ctenophores have comb plates. (ii) Sponges have choanocytes. (iii) Cnidarians have a mesoglea. (iv) Echinoderms have a water vascular system. (v) Arthropods have malpighian tubules. How many are correct?', 'Five', ['Four', 'Three', 'Two'], 'All five are NCERT features.', 'Do not look for a false one.', 'statements');
stm(5, 'basis', 'Animals with a true coelom are called eucoelomates.', 'Annelids, molluscs, arthropods, echinoderms and chordates are coelomates.', 0, 'Both are correct.');

// ---- Matches
match(2, 'phyla', 'akx1', 'Animal and phylum', ['A. Hydra', 'B. Ascaris', 'C. Pila', 'D. Asterias'], ['p. Mollusca', 'q. Echinodermata', 'r. Cnidaria', 's. Aschelminthes'], 'A-r, B-s, C-p, D-q', ['A-s, B-r, C-p, D-q', 'A-r, B-s, C-q, D-p', 'A-p, B-s, C-r, D-q'], 'Hydra: Cnidaria. Ascaris: Aschelminthes. Pila: Mollusca. Asterias: Echinodermata.');
match(3, 'phyla', 'akx2', 'Phylum and key feature', ['A. Porifera', 'B. Ctenophora', 'C. Echinodermata', 'D. Annelida'], ['p. Comb plates', 'q. Choanocytes', 'r. Water vascular system', 's. Metameric segmentation'], 'A-q, B-p, C-r, D-s', ['A-p, B-q, C-r, D-s', 'A-q, B-p, C-s, D-r', 'A-r, B-p, C-q, D-s'], 'Choanocytes in sponges; comb plates in ctenophores; water vascular system in echinoderms; metamerism in annelids.');
